public static void main(String[] args){
	Scanner sc = new Scanner(System.in);
	int w = sc.nextInt();
	int b = sc.nextInt();
	String wb = "wbwbwwbwbwbw";
	int patternLength = wb.length();
	int windowLength = w + b;

	for (int start = 0; start < patternLength; start++) {
		int wnum = 0, bnum = 0;
		for (int i = 0; i < windowLength; i++) {
			char c = wb.charAt((start + i) % patternLength);
			if (c == 'w') wnum++;
			else bnum++;
		}
		if (wnum == w && bnum == b) {
			System.out.println("Yes");
			return;
		}
	}
	System.out.println("No");
}

